const out = [];
for (let i = 0; i < 32; i++) out.push({ json: { page: i, archived: 'false' } });
for (let i = 0; i < 12; i++) out.push({ json: { page: i, archived: 'true' } });
return out;

// Rapproche chaque client des archives avec un client Interfast. Aucune IA, aucune ecriture Interfast.
const STOP = new Set(['M','MR','MRS','MME','MLLE','MM','MONSIEUR','MADAME','ET','EPOUX','SCI','SARL','SAS','SASU','SA','EURL','STE','SOCIETE','LA','LE','LES','DE','DU','DES','D','L','RESTAURANT','HOTEL','LOCATAIRE','CHEZ','CABINET','MAITRE','DR','THE','AND','OF']);
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();
const toks = s => [...new Set(norm(s).split(' ').filter(t => t.length >= 2 && !STOP.has(t)))];
const cp5 = s => { const d = String(s || '').replace(/\D/g, ''); return d ? d.padStart(5, '0').slice(0, 5) : ''; };
function lev1(a, b) { if (Math.abs(a.length - b.length) > 1) return false; let i = 0, j = 0, e = 0; while (i < a.length && j < b.length) { if (a[i] === b[j]) { i++; j++; continue; } if (++e > 1) return false; if (a.length > b.length) i++; else if (b.length > a.length) j++; else { i++; j++; } } return e + (a.length - i) + (b.length - j) <= 1; }
const same = (a, b) => a === b || (a.length >= 5 && b.length >= 5 && (lev1(a, b) || a.startsWith(b) || b.startsWith(a)));
const ifc = {};
for (const it of $('Clients Interfast').all()) for (const c of (it.json.items || [])) {
  if (!c || c.category === 'supplier' || ifc[c.id]) continue;
  const ad = c.address || {};
  ifc[c.id] = { id: String(c.id), ref: c.reference || '', nom: c.name || '', T: toks(c.name), cp: cp5(ad.zipCode), ville: norm(ad.city), villeAff: ad.city || '', archived: !!c.archived };
}
const liste = Object.values(ifc);
if (liste.length < 500) throw new Error('Liste clients Interfast incomplete (' + liste.length + ') : rien n est ecrit');
// Un mot present chez 8 clients Interfast ou plus (prenom, PROPERTIES...) ne suffit pas a lui seul
const df = {};
for (const c of liste) for (const t of c.T) df[t] = (df[t] || 0) + 1;
const rare = t => (df[t] || 0) < 8;
function nameScore(A, B) {
  if (!A.length || !B.length) return { s: 0, hit: 0, rareHit: 0, exact: 0, exactFull: false, cover: 0 };
  let hit = 0, rareHit = 0, exact = 0;
  for (const a of A) { const b = B.find(x => same(a, x)); if (b) { hit++; if (b === a) exact++; if (rare(a) || rare(b)) rareHit++; } }
  return { s: hit / Math.min(A.length, B.length), hit, rareHit, exact, exactFull: exact >= Math.min(A.length, B.length), cover: hit / Math.max(A.length, B.length) };
}
const idx = {};
for (const c of liste) for (const t of c.T) { (idx[t] = idx[t] || []).push(c); if (t.length >= 5) { const p = '#' + t.slice(0, 5); (idx[p] = idx[p] || []).push(c); } }
const groupes = {};
for (const it of $('Lire index').all()) {
  const r = it.json || {};
  if (String(r.statut || '') !== 'ok') continue;
  const dossier = String(r.dossier_client || '').trim();
  const fourreTout = !dossier || /ANCIENS CLIENTS|racine/i.test(dossier);
  const cle = fourreTout ? (dossier || '(racine)') + ' / ' + String(r.client || '').trim() : dossier;
  const g = groupes[cle] = groupes[cle] || { cle, dossier: fourreTout ? '' : dossier, noms: {}, villes: {}, cps: {}, dates: [], mat: new Set(), ht: 0, n: 0 };
  g.n++;
  if (r.client) g.noms[r.client] = (g.noms[r.client] || 0) + 1;
  if (r.ville) g.villes[norm(r.ville)] = r.ville;
  const cp = cp5(r.code_postal); if (cp) g.cps[cp] = 1;
  if (r.date_facture) g.dates.push(String(r.date_facture).slice(0, 10));
  const m = [r.marque, r.modele].filter(Boolean).join(' ').trim(); if (m) g.mat.add(m);
  const ht = parseFloat(String(r.montant_ht || '').replace(/\s/g, '').replace(',', '.')); if (!isNaN(ht)) g.ht += ht;
}
const deja = new Set($('Lire correspondance').all().map(i => String((i.json || {}).cle || '').trim()).filter(Boolean));
const out = [];
for (const g of Object.values(groupes)) {
  if (deja.has(g.cle)) continue;
  const Tdossier = toks(g.dossier);
  const variantes = [g.dossier, ...Object.keys(g.noms)].filter(Boolean).map(toks).filter(t => t.length);
  const cand = new Map();
  for (const T of variantes) for (const t of T) { for (const c of (idx[t] || [])) cand.set(c.id, c); if (t.length >= 5) for (const c of (idx['#' + t.slice(0, 5)] || [])) cand.set(c.id, c); }
  const scores = [];
  for (const c of cand.values()) {
    // Le nom du dossier client (souvent le nom de famille) doit se retrouver dans la fiche Interfast
    if (Tdossier.length && !Tdossier.some(a => c.T.some(b => same(a, b)))) continue;
    let best = { s: 0, hit: 0, rareHit: 0, exact: 0, exactFull: false, cover: 0 };
    let minS = 1;
    for (const T of variantes) { const r = nameScore(T, c.T); minS = Math.min(minS, r.s); if (r.s > best.s || (r.s === best.s && r.cover > best.cover)) best = r; }
    if (best.s < 0.5 || best.rareHit === 0) continue;
    const geoCp = !!(c.cp && g.cps[c.cp]);
    const geoVille = !!(c.ville && g.villes[c.ville]);
    const geo = geoCp || geoVille;
    // Correspondance partielle ou approximative (orthographe voisine) sans la meme ville : trop faible
    if ((best.s < 1 || best.exact < best.hit) && !geo) continue;
    const total = best.s + (geoCp ? 0.25 : 0) + (geoVille ? 0.15 : 0) + Math.min(best.hit - 1, 2) * 0.05 + best.cover * 0.1;
    scores.push({ c, b: best, minS, geo, total });
  }
  scores.sort((a, b) => b.total - a.total);
  const top = scores[0], second = scores[1];
  let statut = 'absent';
  if (top) {
    const net = !second || top.total - second.total >= 0.2;
    // sur = meme nom exact, meme ville, aucun autre candidat proche, et pas de prenom different
    const prenomOk = top.minS === 1 || top.c.T.length === 1;
    statut = (top.b.s === 1 && top.b.exactFull && top.geo && net && prenomOk) ? 'sur' : 'a_verifier';
  }
  const d = g.dates.sort();
  const a1 = d.length ? d[0].slice(0, 4) : '', a2 = d.length ? d[d.length - 1].slice(0, 4) : '';
  const nomPrincipal = Object.entries(g.noms).sort((a, b) => b[1] - a[1]).map(x => x[0])[0] || g.dossier;
  out.push({
    cle: g.cle, statut, decision_laurent: '', nb_factures: g.n,
    periode: a1 === a2 ? a1 : a1 + '-' + a2,
    villes: Object.values(g.villes).slice(0, 3).join(', '),
    materiel: [...g.mat].slice(0, 6).join(' ; ').slice(0, 250),
    total_ht: Math.round(g.ht * 100) / 100,
    client_archives: nomPrincipal,
    interfast_nom: top ? top.c.nom.trim() + (top.c.archived ? ' (archive)' : '') : '',
    interfast_ref: top ? top.c.ref : '', interfast_id: top ? top.c.id : '',
    interfast_ville: top ? top.c.villeAff : '',
    score: top ? Math.round(top.total * 100) / 100 : 0,
    autre_candidat: second ? second.c.nom.trim() + ' (' + second.c.ref + ', ' + second.c.villeAff + ')' : '',
    note_interfast: ''
  });
}
const ordre = { a_verifier: 0, sur: 1, absent: 2 };
out.sort((a, b) => ordre[a.statut] - ordre[b.statut] || b.nb_factures - a.nb_factures);
return out.map(j => ({ json: j }));
